from datetime import date, timedelta

class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = {}  # book_id -> {'borrowed_by': user, 'borrow_date': date} or None if available
        self.users = {}  # user -> {'current_book': book_id, 'fines': float}

    def add_book(self, book_id: str) -> None:
        self.books[book_id] = None

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        if self.books[book_id] is not None:
            raise ValueError(f"Book {book_id} is already borrowed")

        # Check if user already has a book (unless they have unpaid fines, they can hold at most one)
        if user in self.users and self.users[user].get('current_book') is not None:
            # User already has a book - check if they have unpaid fines
            if self.users[user].get('fines', 0.0) == 0.0:
                raise ValueError(f"User {user} already has a book")

        # Set up user if not exists
        if user not in self.users:
            self.users[user] = {'current_book': None, 'fines': 0.0}

        # Update book status
        self.books[book_id] = {'borrowed_by': user, 'borrow_date': day}

        # Update user's current book
        self.users[user]['current_book'] = book_id

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        book_info = self.books[book_id]
        if book_info is None:
            raise ValueError(f"Book {book_id} is not borrowed")

        if book_info['borrowed_by'] != user:
            raise ValueError(f"User {user} did not borrow book {book_id}")

        # Calculate fine
        borrow_date = book_info['borrow_date']
        due_date = borrow_date + timedelta(days=self.loan_days)

        fine = 0.0
        if day > due_date:
            # Count only weekdays (Mon-Fri) as delay days
            delay_days = 0
            current_date = due_date + timedelta(days=1)
            while current_date <= day:
                # Monday=0, Sunday=6, so weekends are 5 and 6
                if current_date.weekday() < 5:  # Monday to Friday
                    delay_days += 1
                current_date += timedelta(days=1)

            fine = delay_days * self.daily_fine

        # Update user's fines
        if user not in self.users:
            self.users[user] = {'current_book': None, 'fines': 0.0}
        self.users[user]['fines'] += fine

        # Update book status
        self.books[book_id] = None

        # Clear user's current book
        self.users[user]['current_book'] = None

        return fine

    def unpaid_fines(self, user: str) -> float:
        if user not in self.users:
            return 0.0
        return self.users[user].get('fines', 0.0)

    def pay(self, user: str) -> None:
        if user in self.users:
            self.users[user]['fines'] = 0.0
